import{_ as a,H as e,f as t,i as r}from"./chunks/framework.Cvt1eIE0.js";const I=JSON.parse('{"title":"PIGLIN KING 第二巻 黒曜石戦争","description":"","frontmatter":{"title":"PIGLIN KING 第二巻 黒曜石戦争","outline":"deep"},"headers":[],"relativePath":"story/2-1.md","filePath":"story/2-1.md"}'),o={name:"story/2-1.md"};function i(n,p,l,h,s,d){return e(),t("div",null,[...p[0]||(p[0]=[r('<h1 id="piglin-king" tabindex="-1">PIGLIN KING <a class="header-anchor" href="#piglin-king" aria-label="Permalink to &quot;PIGLIN KING&quot;">​</a></h1><h2 id="第二巻-黒曜石戦争" tabindex="-1">第二巻 黒曜石戦争 <a class="header-anchor" href="#第二巻-黒曜石戦争" aria-label="Permalink to &quot;第二巻 黒曜石戦争&quot;">​</a></h2><hr><h1 id="第一章-黄金時代" tabindex="-1">第一章 黄金時代 <a class="header-anchor" href="#第一章-黄金時代" aria-label="Permalink to &quot;第一章 黄金時代&quot;">​</a></h1><p>王国歴十二年。</p><p>平和は、拍子抜けするほど静かだった。</p><p>静かなわけではない。</p><p>ただ、戦のない日々があまりに長く続いたせいで、誰もが「これが当たり前なのだ」と思い込むようになっていた。</p><p>PIGLIN KINGDOMはかつてない繁栄を迎えていた。</p><p>崩れた砦は、一つ残らず修復された。石を積み直す音が、かつて炎に焼かれた村々に響いた。</p><p>寸断されていた交易路は、隅々まで整備された。荷馬車の列が、玄武岩デルタを縫うように行き来した。</p><p>戦乱の記憶は、もう遠い昔話になっていた。子供たちは、戦争を知らずに育っていた。</p><p>王都 GOLDEN BASTION。</p><p>その名は、伝説の冠から取られた。黄金の砦。希望の砦。</p><p>今日も市場には笑い声があふれていた。</p><p>肉を焼く匂い。</p><p>鉄を打つ音――鍛冶屋の槌が、規則正しく石畳に響いていた。その音を聞くたびに、オーレックスは、ふと父の手を思い出すことがあった。鉄のように硬く、しかし優しかった、あの手を。</p><p>「平和ってのはいいもんだな！！」</p><p>スターリンは巨大な肉の塊を頬張りながら、満足げに笑った。</p><p>頬には、肉汁が垂れていた。</p><p>「君は食べてばかりだね。」</p><p>ピックバーグは苦笑しながら、羊皮紙をめくった。彼は今、王立図書館の館長を任されていた。眼鏡の奥の目は、変わらず、何かを観察し続けていた。</p><p>「だって美味いんだもん。」</p><p>「将軍がそんなことで満足していいのか。」</p><p>「将軍だからこそ満足するんだよ。腹が減ってちゃ斧も振れねえ。」</p><p>二人のやりとりは、何年経っても変わらなかった。それが、オーレックスにとってはどこか、安心できる風景だった。</p><p>王座の間。</p><p>KING PIGLIN I――</p><p>Aurex Goldtuskは、積み上げられた報告書に目を通していた。</p><p>豊作の報告。橋の修繕完了の報告。新しい学校が開かれたという報告。</p><p>どれも、いい報告だった。</p><p>「悪いことがないっていうのは、変な感じだな。」</p><p>そう呟いた瞬間だった。</p><p>「陛下！」</p><p>王立情報局の兵士が、息を切らして飛び込んできた。顔は青く、声は震えていた。</p><p>「大変です！」</p><p>「北方要塞との通信が途絶しました！」</p><p>その一言で。</p><p>市場のざわめきが、遠い世界の出来事のように感じられた。</p><p>報告書の上で、オーレックスの手が止まった。</p><hr><h1 id="第二章-消えた調査隊" tabindex="-1">第二章 消えた調査隊 <a class="header-anchor" href="#第二章-消えた調査隊" aria-label="Permalink to &quot;第二章 消えた調査隊&quot;">​</a></h1><p>「通信が途絶した、というのは。」</p><p>オーレックスは静かに尋ねた。声に動揺は見せなかった。王として、それだけは身につけていた。</p><p>「定期連絡が、三日前から届いておりません。伝令鳥も戻ってきません。」</p><p>「事故の可能性は？」</p><p>「分かりません。だからこそ、調査隊を送りました。」</p><p>その調査隊も。</p><p>戻ってこなかった。</p><p>数日後。</p><p>「第二調査隊も消息を絶ちました。」</p><p>その報告を聞いた瞬間、会議室の空気が変わった。</p><p>「おかしい。」</p><p>ピックバーグは地図に屈み込んだ。蝋燭の灯りが、彼の眼鏡に細かく反射していた。北方要塞を示す印に、指を這わせる。</p><p>「二つの要塞が、同時に黙る。事故なら、こうはならない。」</p><p>「盗賊か？」</p><p>スターリンが腕を組んだ。</p><p>「盗賊なら、もっと雑な痕跡を残す。略奪、悲鳴、火の手。何かが残る。」</p><p>「何も残らない、ということは。」</p><p>ピックバーグは顔を上げた。</p><p>「何かが、何も残さないように消した、ということだ。」</p><p>部屋に、沈黙が落ちた。</p><p>オーレックスは、地図の北方要塞をじっと見つめていた。</p><p>あの夜のことを、思い出さずにいられなかった。真紅の森が燃えた夜。あの時も、前触れはあった。旅商人が減り、難民が増え、父の表情が硬くなった。そして、気づいた時には、全てが燃えていた。</p><p>「もっと嫌な予感がする。」</p><p>オーレックスは静かに言った。</p><p>「気づくのが、遅すぎたことが、前にもあった。」</p><p>スターリンとピックバーグは、何も言わなかった。</p><p>ただ、二人とも、同じ夜を覚えていた。</p><p>「親衛隊を率いる。」</p><p>オーレックスは立ち上がった。</p><p>「僕が、直接見に行く。」</p><p>「陛下、それは――」</p><p>「危険は分かってる。」</p><p>オーレックスは、王座の間の窓から、暗いネザーの空を見た。</p><p>「でも、今度こそ、見過ごしたくない。」</p><p>その言葉に、誰も反論できなかった。</p><hr><h1 id="第三章-黒曜石の塔" tabindex="-1">第三章 黒曜石の塔 <a class="header-anchor" href="#第三章-黒曜石の塔" aria-label="Permalink to &quot;第三章 黒曜石の塔&quot;">​</a></h1><p>北方要塞へ続く道は、長く、静かだった。</p><p>静かすぎた。</p><p>普段なら、行商人の荷馬車の音や、警備兵の掛け声が、遠くから聞こえてくるはずだった。</p><p>何も、聞こえなかった。</p><p>要塞が見えてきた時、三人は同時に足を止めた。</p><p>そこにあったのは、静寂だった。</p><p>兵士もいない。</p><p>住民もいない。</p><p>誰一人、いない。</p><p>門は、開いたままだった。風もないネザーで、それでも何かが、わずかに動いた気がした。</p><p>「なんだ……ここ。」</p><p>スターリンの声が、いつもより低かった。大斧の柄を握る手に、力が入っていた。</p><p>兵舎の中を覗くと、食事の皿が、そのまま残されていた。冷えた肉。手をつけられていないパン。誰かが食べようとした瞬間に、消えたかのように。</p><p>「まるで……。」</p><p>ピックバーグが囁いた。</p><p>「誰かが、時間そのものを止めて、人だけを抜き取ったみたいだ。」</p><p>その時。</p><p>要塞の中央に、それが見えた。</p><p>「……記録に存在しない。」</p><p>巨大な黒曜石の塔。</p><p>そこにあるはずのない構造物が、まるで最初からそこにあったかのように、静かに、傲然と聳えていた。</p><p>表面には、紫色の光が、まるで脈打つように、ゆっくりと走っていた。心臓の鼓動のように。</p><p>「こんな建物……。」</p><p>「分かってる。」</p><p>オーレックスは塔を見上げた。</p><p>その時。</p><p>ギィィィ……</p><p>空間が、裂けた。</p><p>音もなく。</p><p>ただ、そこにあった空気が、紫色の裂け目に変わった。</p><p>裂け目の向こうから、漆黒の影が、ゆっくりと滲み出てきた。</p><p>「……人？」</p><p>否。</p><p>人ではなかった。</p><p>紫色に光る目。</p><p>異様に長い手足。</p><p>漆黒の身体。</p><p>「エンダーマンだ！」</p><p>兵士たちが叫んだ。</p><p>しかし、それは、誰も見たことのないエンダーマンだった。</p><p>黒曜石の鎧をまとい、隊列を組み、一体一体が、明確な意志を持って、こちらを見ていた。</p><p>「侵入者。」</p><p>声が、不気味に、空間そのものから響いた。</p><p>「排除する。」</p><p>そして、戦いが始まった。</p><p>剣と剣がぶつかる音。</p><p>転移する影。</p><p>紫色の閃光。</p><p>スターリンの大斧が、空気を切り裂く。</p><p>「うおおおおお！！」</p><p>一体を吹き飛ばす。だが、すぐに次の一体が、瞬きの間に背後へ転移していた。</p><p>「後ろ！！」</p><p>ピックバーグの声に、オーレックスが振り返り、剣を一閃させる。</p><p>父から叩き込まれた剣術。骨の髄まで染み込んだ、あの動き。今、この瞬間も、それが彼を守っていた。</p><p>激戦は、長く続いた。</p><p>それでも。</p><p>三人と親衛隊は、敵を退けた。</p><p>しかし。</p><p>戦いの後に残ったのは、勝利の喜びではなかった。</p><hr><h1 id="第四章-黒曜石帝国" tabindex="-1">第四章 黒曜石帝国 <a class="header-anchor" href="#第四章-黒曜石帝国" aria-label="Permalink to &quot;第四章 黒曜石帝国&quot;">​</a></h1><p>敵兵が消えた跡には、奇妙な紋章を刻んだ鎧の残骸が落ちていた。</p><p>黒曜石と、紫色の目。</p><p>そして、見たことのない古代文字。</p><p>ピックバーグは、それを拾い上げ、月明かりもないネザーの空の下で、じっと見つめた。</p><p>顔色が、変わっていく。</p><p>「まさか……。」</p><p>「そんな……。」</p><p>「知っているのか？」</p><p>スターリンが尋ねた。</p><p>ピックバーグはゆっくりと答えた。声が、震えていた。</p><p>「古文書の伝説だ。」</p><p>「エンドの民。」</p><p>「黒曜石帝国。」</p><p>「数千年前に滅んだとされる、文明……。」</p><p>その文字は、かつて忘れられた砦で見た古代ヴォールト文明の文字とは、まったく異質だった。あの文明は、罠と知恵で遺跡を守っていた。これは違う。これは、もっと冷たく、もっと、組織化されたものの匂いがした。</p><p>「でも。」</p><p>「もし本当に存在するなら。」</p><p>「これは戦争になる。」</p><p>その瞬間。</p><p>遠くの空が、紫色に染まった。</p><p>数え切れないほどの転移門が、地平線の端から端まで、まるで星が降るように、次々と開いていった。</p><p>その向こうから。</p><p>無数の黒い影が、姿を現した。</p><p>軍隊だった。</p><p>統率された、巨大な軍隊だった。</p><p>「全軍！」</p><p>「戦闘準備！」</p><p>声が、要塞中に響いた。</p><p>オーレックスは、紫色に染まった空を見上げた。</p><p>遠い昔のあの夜、真紅の森を染めた炎の色とは違う。だが、何かが、同じだった。</p><p>平和な日々が、また終わろうとしている。その予感だけが、確かにあった。</p><p>こうして。</p><p>後に</p><p>『黒曜石戦争』</p><p>と呼ばれる戦いが、始まった。</p>',175)])])}const _=a(o,[["render",i]]);export{I as __pageData,_ as default};
